import { expect, expectStatus, test } from "../../fixtures";

test.describe("vendor names are unique within a tenant", () => {
  test("creating a vendor whose name differs only by case returns vendor_name_taken", { tag: "@VEN-03" }, async ({ apiAs }) => {
    // Arrange: unique suffix so parallel runs against the shared database don't collide
    const member = await apiAs("member");
    const suffix = `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}`;
    const existingName = `Acme Freight ${suffix}`;

    const seeded = await member.post("/api/vendors", {
      data: {
        name: existingName,
        category: "logistics",
        contact_email: "ops@acmefreight.example",
      },
    });
    await expectStatus(seeded, 201);

    // Act: same name, different casing
    const response = await member.post("/api/vendors", {
      data: {
        name: `acme freight ${suffix}`,
        category: "logistics",
        contact_email: "ops@acmefreight.example",
      },
    });

    // Assert
    const body = await expectStatus(response, 409);
    expect(body.error.code).toBe("vendor_name_taken");
  });
});
